    expect(sidebar).toBeNull()
  })

  it('should be visible when isOpen is true', () => {
    render(<Sidebar isOpen={true} onClose={() => {}} sections={[{ title: 'Test', links: [] }]} />)
    expect(screen.getByText('Test')).toBeDefined()
