    const { container } = render(
      <Sidebar isOpen={true} onClose={() => {}} sections={sections} />,
    )
    const backdrop = container.querySelector('button[aria-hidden="true"]')
    expect(backdrop).not.toBeNull()
    expect(backdrop).toHaveAttribute('tabindex', '-1')
  })
