"use client";

import { useEffect, useRef, useState } from "react";
import Block from "@/components/block";
import { Bars3Icon } from "@heroicons/react/24/outline";
import { useSession, signOut } from "next-auth/react";
import Link from "next/link";
import SidebarWrapper from "./sidebar-wrapper";
import { SIDEBAR_DIALOG_ID } from "./sidebar";
import { Suspense } from "react";
import { ACTION_BOUNDARY, ACTION_FOCUS } from "@/lib/control-classes";

export const Header = () => {
  const { data: session, status } = useSession();
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);
  const triggerRef = useRef<HTMLButtonElement>(null);

  // Focus return, after the close rather than during it, because the drawer
  // moves focus into itself on open and closing would otherwise drop it on
  // <body> -- where the next Tab restarts at the top of the document.
  // `chat.tsx` fixes the same thing for its launcher.
  //
  // Three of the four close routes, not four. Escape, the Close button and the
  // backdrop end here with focus on the trigger. Following a link does not:
  // this effect runs and focuses the trigger, and Next's route-change focus
  // reset then moves focus to <body> afterwards. Measured -- the `focusin`
  // trace across a navigation reads `A "FAQ"` then `BUTTON "Open menu"`, and
  // final focus is BODY.
  //
  // Left alone, because on a navigation that is the router's call to make and
  // it announces the new route. It looks like restoration from outside only
  // because the trigger is the document's first tabbable element, so the next
  // Tab reaches it either way -- an ordering coincidence rather than the
  // mechanism, which is exactly why it is written down here.
  //
  // `preventScroll`, because the header is in normal flow at the top of
  // `<main>` rather than sticky, so a plain `focus()` scrolls the off-screen
  // trigger back into view and takes the reader's place with it. Measured on
  // /faq at 390x844 with the scroll set to 900: 900 -> 0 without the option,
  // 900 -> 900 with it, on all three close routes.
  //
  // That 900 is a scroll set after opening, not a position the drawer can be
  // opened from, and how much of it a user can reach is much smaller -- worth
  // saying so the next reader does not overrate this. `position: static` puts
  // the trigger's rect at [-1, 43], so it is gone from the viewport at
  // scrollY=43 exactly: past that it cannot be clicked, and tabbing to it
  // scrolls the page to 0 first, by the browser's own sequential-focus
  // behaviour rather than by this call. So the jump this prevents is bounded at
  // about 43px, not 900.
  //
  // Kept anyway. It costs nothing, and it becomes load-bearing the moment the
  // header goes sticky -- which is the change most likely to arrive here, and
  // would silently widen that window to the whole page.
  //
  // The trade in the same window: focus now returns to a trigger that may be
  // partially clipped (13px of 44 at scrollY=30) where a plain `focus()` would
  // have scrolled it fully into view. Both are defensible under ~43px, and the
  // thing that actually resolves both is a sticky header.
  const wasOpen = useRef(false);
  useEffect(() => {
    if (wasOpen.current && !isSidebarOpen) {
      triggerRef.current?.focus({ preventScroll: true });
    }
    wasOpen.current = isSidebarOpen;
  }, [isSidebarOpen]);

  return (
    <>
      <Block
        outerClassName=""
        innerClassName="h-12 flex flex-row center items-center"
      >
        <div className="text-slate-800">
          {/* The only thing on the page that says whether the drawer is open,
              and before #306 it said nothing: `aria-expanded` was absent in
              both states and the label stayed "Open menu" while the menu was
              open. The label tracks the state as well as the attribute, since
              a name that contradicts `aria-expanded` is its own defect. */}
          <button
            ref={triggerRef}
            type="button"
            className="-m-2.5 inline-flex items-center justify-center rounded-md p-2.5 text-gray-700"
            onClick={() => setIsSidebarOpen((open) => !open)}
            aria-label={isSidebarOpen ? "Close menu" : "Open menu"}
            aria-expanded={isSidebarOpen}
            aria-controls={SIDEBAR_DIALOG_ID}
          >
            <Bars3Icon className="h-6 w-6" aria-hidden="true" />
          </button>
        </div>
        <div className="grow">&nbsp;</div>
        <div className="flex flex-row items-center gap-3">
          {status === "authenticated" ? (
            <>
              <Link href="/profile" className="flex flex-row items-center gap-3 hover:bg-gray-50 p-1 rounded-md transition-colors" title="Profile Settings">
                <div>
                  <div className="text-right font-semibold text-zinc-600">
                    {session.user?.name || session.user?.email}
                  </div>
                  <div className="text-right text-xs text-zinc-400">
                    {session.user?.email}
                  </div>
                </div>
                <div className="">
                  {session.user?.image ? (
                    <img
                      src={session.user.image}
                      width={32}
                      height={32}
                      alt={session.user.name || "User"}
                      className="rounded-full h-8 w-8 object-cover"
                    />
                  ) : (
                    <div className="h-8 w-8 rounded-full bg-gray-300 flex items-center justify-center text-gray-600">
                      {session.user?.name?.[0] || session.user?.email?.[0]}
                    </div>
                  )}
                </div>
              </Link>
              <button
                onClick={() => signOut()}
                className={`ml-4 px-3 py-1.5 text-sm font-semibold text-white bg-indigo-600 rounded-md hover:bg-indigo-500 focus-visible:outline-indigo-600 ${ACTION_BOUNDARY}`}
              >
                Sign Out
              </button>
            </>
          ) : (
            <>
              <Link href="/login" className={`px-3 py-1.5 text-sm font-semibold text-white bg-indigo-600 rounded-md hover:bg-indigo-500 focus-visible:outline-indigo-600 ${ACTION_BOUNDARY}`}>
                Sign In
              </Link>
              <Link href="/signup" // `ACTION_FOCUS`, not `ACTION_BOUNDARY`: outlined rather than
                // filled, so it already has an edge forced colors keeps, and
                // the constant's `border-2` would render it identically to the
                // filled Sign In beside it.
                className={`ml-2 px-3 py-1.5 text-sm font-semibold text-indigo-600 border border-indigo-600 rounded-md hover:bg-indigo-50 hover:text-indigo-700 focus-visible:outline-indigo-600 ${ACTION_FOCUS}`}>
                Sign Up
              </Link>
            </>
          )}
        </div>
      </Block>

      <Suspense fallback={null}>
        <SidebarWrapper 
          isOpen={isSidebarOpen} 
          onClose={() => setIsSidebarOpen(false)} 
        />
      </Suspense>
    </>
  );
};

export default Header;

